import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()]
});

module.exports = {
  content: ['./index.html', './src/**/*.{js,jsx,ts,tsx}'],
  theme: {
    extend: {
      fontFamily: {
        sans: ['Inter', 'system-ui', 'sans-serif']
      }
    }
  },
  plugins: []
};

@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  @apply bg-gray-100 text-gray-900;
}

.sidebar {
  @apply fixed top-0 left-0 h-full w-72 bg-white shadow-md;
}

.content {
  @apply ml-72 p-4;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import Sidebar from './components/Sidebar';
import ContentArea from './components/ContentArea';

function App() {
  return (
    <div className="flex">
      <Sidebar />
      <ContentArea />
    </div>
  );
}

export default App;

import axios from 'axios';

const apiClient = axios.create({
  baseURL: import.meta.env.VITE_API_URL,
  headers: {
    'Authorization': 'API-KEY',
    'X-API-KEY': import.meta.env.VITE_X_API_KEY
  }
});

export const fetchSidebarMenus = () => {
  return apiClient.get(`/v3/menus`, {
    params: {
      'parent_id': import.meta.env.VITE_MAIN_MENU_ID,
      'project-id': import.meta.env.VITE_PROJECT_ID
    }
  });
};

export const fetchTableDetails = (menuId) => {
  return apiClient.get(`/v3/table_details`, {
    params: {
      'menu_id': menuId,
      'project-id': import.meta.env.VITE_PROJECT_ID
    }
  });
};

import React, { useEffect, useState } from 'react';
import { fetchSidebarMenus } from '../api';

function Sidebar() {
  const [menus, setMenus] = useState([]);

  useEffect(() => {
    fetchSidebarMenus().then(response => {
      setMenus(response.data.menus);
    });
  }, []);

  return (
    <div className="sidebar">
      <ul>
        {menus.map(menu => (
          <li key={menu.id} className="p-4 border-b">
            {menu.label}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Sidebar;

import React, { useState } from 'react';
import GeneratedForm from './GeneratedForm';
import DataTable from './DataTable';

function ContentArea() {
  const [selectedMenu, setSelectedMenu] = useState(null);

  return (
    <div className="content">
      {selectedMenu ? (
        <>
          <GeneratedForm menuId={selectedMenu.id} />
          <DataTable menuId={selectedMenu.id} />
        </>
      ) : (
        <p>Select a menu item to view details.</p>
      )}
    </div>
  );
}

export default ContentArea;

import React, { useEffect, useState } from 'react';
import { fetchTableDetails } from '../api';

function GeneratedForm({ menuId }) {
  const [fields, setFields] = useState([]);

  useEffect(() => {
    fetchTableDetails(menuId).then(response => {
      setFields(response.data.fields);
    });
  }, [menuId]);

  return (
    <form className="space-y-4">
      {fields.map(field => {
        switch (field.type) {
          case 'SINGLE_LINE':
            return <input key={field.id} type="text" placeholder={field.label} className="w-full p-2 border" />;
          case 'NUMBER':
            return <input key={field.id} type="number" placeholder={field.label} className="w-full p-2 border" />;
          case 'TEXT':
            return <textarea key={field.id} placeholder={field.label} className="w-full p-2 border"></textarea>;
          case 'BOOLEAN':
            return <label key={field.id} className="flex items-center">
              <input type="checkbox" className="mr-2" /> {field.label}
            </label>;
          case 'DATE':
            return <input key={field.id} type="date" className="w-full p-2 border" />;
          case 'ENUM':
            return (
              <select key={field.id} className="w-full p-2 border">
                {field.options.map(option => (
                  <option key={option.value} value={option.value}>{option.label}</option>
                ))}
              </select>
            );
          default:
            return null;
        }
      })}
    </form>
  );
}

export default GeneratedForm;

import React, { useEffect, useState } from 'react';
import { fetchTableDetails } from '../api';

function DataTable({ menuId }) {
  const [data, setData] = useState([]);

  useEffect(() => {
    fetchTableDetails(menuId).then(response => {
      setData(response.data.rows);
    });
  }, [menuId]);

  return (
    <table className="min-w-full bg-white">
      <thead>
        <tr>
          {data.length > 0 && Object.keys(data[0]).map(key => (
            <th key={key} className="py-2 px-4 border-b">{key}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.map((row, index) => (
          <tr key={index} className="hover:bg-gray-100">
            {Object.values(row).map((value, i) => (
              <td key={i} className="py-2 px-4 border-b">{value}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default DataTable;
